{"script": "#!/bin/bash\n\n# Create the "files_list" directory if it doesn't exist\nmkdir -p files_list\n\n# Check if the input file is provided as an argument\nif [ $# -eq 0 ]; then\n    echo "Usage: $0 <input_file>"\n    exit 1\nfi\n\n# Input file path\ninput_file="$1"\n\n# Check if the input file exists and is readable\nif [ ! -f "$input_file" ] || [ ! -r "$input_file" ]; then\n    echo "Error: File '$input_file' does not exist or is not readable."\n    exit 1\nfi\n\n# Move the input file into the "files_list" directory\nmv "$input_file" files_list/\n\n# Check if the move was successful\nif [ $? -ne 0 ]; then\n    echo "Error: Failed to move '$input_file' into 'files_list' directory."\n    exit 1\nfi\n\n# Initialize counter for files with the specified extension\ncount=0\n\n# Specify the file extension to search for (e.g., ".txt")\nextension=".txt"\n\n# Read each line from the input file and check if it ends with the specified extension\nwhile IFS= read -r filename; do\n    # Check if the filename ends with the specified extension\n    if [[ "$filename" == *"$extension" ]]; then\n        ((count++))\n    fi\n    # Remove the file from the directory after processing (optional, depending on requirements)\n    rm -f "files_list/$filename"
    done < "files_list/$(basename "$input_file")"

# Output the total count of files with the specified extension\necho $count"}

